{
  "name": "E-662压电定位控制器",
  "name_en": "E-662 Piezo Positioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于控制压电定位通道的硬件控制器，可将指定通道移动到目标位置、读取当前位置，并查询控制就绪状态、通道对象、通道相位以及位置上下限。常用于显微镜精密对焦和纳米级位移定位。",
  "description_en": "A hardware controller for piezo positioning channels. It can move a selected channel to a target position, read the current position, and query control readiness, channel object, channel phase, and position limits. It is commonly used for precision microscope focusing and nanoscale positioning.",
  "actions": [
    {
      "action_name": "auto-MoveTo",
      "description": "将指定压电通道移动到目标位置。",
      "description_en": "Move the specified piezo channel to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定压电通道的当前位置。",
      "description_en": "Get the current position of the specified piezo channel."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否已就绪。",
      "description_en": "Query whether the controller is ready."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取通道对象参数。",
      "description_en": "Get the channel object parameter."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取通道相位参数。",
      "description_en": "Get the channel phase parameter."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限制。",
      "description_en": "Get the minimum position limit for the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限制。",
      "description_en": "Get the maximum position limit for the specified channel."
    }
  ],
  "tag_hints": [
    "piezo positioning",
    "nanopositioning",
    "microscope focus control",
    "piezo actuator controller",
    "position readback",
    "travel limits",
    "PI E-662"
  ]
}

